'use strict';
window.RUN=()=>{const t=T,L=t.BattleLab,o=[],ok=(c,m)=>o.push((c?'PASS ':'FAIL ')+m);try{
 const start=(left=20,right=20,extra={})=>{if(L.active)L.exit();L.start({leftGroups:[{type:'hum_foot',count:left}],rightGroups:[{type:'hum_foot',count:right}],morale:true,deploy:false,paused:true,ai:false,seed:42,...extra});const b=t.B,g=b.groups[t.playerGroups()[0]],foe=Object.values(b.groups).find(x=>x.foe);b.obs=[];for(const [gr,x] of [[g,300],[foe,340]]){gr.placeAt(x,300);t.layForm(gr.id);gr.units.forEach(u=>{u.x=gr.ax+u.sx;u.y=gr.ay+u.sy;u.cd=999})}return {b,g,foe,r:g.resolve,a:g.units,e:foe.units}};
 const tick=(f,dt)=>{f.b.t+=dt;t.moraleTick(dt)},kill=(f,u=f.a.find(x=>x.hp>0))=>t.applyDmg(u,u.hp+1,1,'slash',f.e[0]);
 let f=start(),r=f.r;ok(r instanceof t.BattleResolve&&f.a.every(u=>t.resolveOf(u)===r),'one authoritative resolve object belongs to the formation');
 f.a[0].mor=-100;f.a[0].confidence=1;tick(f,.01);ok(!r.routed&&f.a.every(u=>u.mor===r.mor&&u.confidence===r.confidence),'individual mirrors cannot make independent morale or confidence decisions');
 const base=r.mor;t.applyDmg(f.a[0],5,1,'slash',f.e[0]);ok(r.mor<base&&f.a.every(u=>u.hp<=0||u.mor===r.mor),'one soldier being hurt feeds one shared group value');
 f=start(10,10);kill(f);const small=f.r.base-f.r.mor;f=start(100,100);for(let i=0;i<10;i++)kill(f);ok(Math.abs((f.r.base-f.r.mor)-small)<1e-7,'the same casualty and HP fraction produces equal immediate morale loss in small and large groups');
 ok(f.r.casualties.length===10&&f.r.initialCount===100,'casualty normalization retains the starting size rather than shrinking the denominator');
 tick(f,0);ok(f.r.lossStrain>0&&t.grpMorale(f.a).weak.includes('recentloss'),'recent group losses create one visible temporary strain');
 const strain=f.r.lossStrain;f.e.forEach(u=>u.x=900);for(let i=0;i<8;i++)tick(f,1);ok(f.r.lossStrain<strain&&f.r.mor<=f.r.ceiling()+1e-8,'stored loss pressure fades without restoring beyond the attrition ceiling');
 f=start(100,25);tick(f,1);ok(f.r.confidence>.1&&f.r.mor>f.r.base,'a stronger formation can become confident');ok(f.a.every(u=>u.confidence===f.r.confidence),'the confidence value is shared by all formation members');
 const badge=t.grpMorale(f.a);t.setOrderUI();ok(badge.confident&&document.querySelector('[data-grp="'+f.g.id+'"] [data-status=confident]'),'the formation confidence badge reads the same authoritative state');
 const before=f.r.mor;for(let i=0;i<10;i++)tick(f,.5);ok(f.r.mor<=Math.min(100,f.r.base+t.CONFIDENCE.max),'numerical confidence remains capped');
 f=start(25,25);tick(f,.2);ok(f.r.confidence===0&&f.foe.resolve.confidence===0,'equal opposing formations do not both become confident');
 f=start(25,100);tick(f,.2);ok(f.foe.resolve.confidence>.1&&f.r.confidence===0,'the enemy side uses the same confidence rules');
 f=start(100,25);tick(f,.1);f.e[0].s={...f.e[0].s,range:300};for(let i=0;i<10;i++)t.applyDmg(f.a[i],Math.floor(f.a[i].hp*.3),1,'pierce',f.e[0]);tick(f,.1);
 ok(f.r.missilePressure>0&&f.r.confidence===0&&!t.grpMorale(f.a).confident,'unanswered missile damage suppresses confidence even with numerical superiority');
 ok(t.grpMorale(f.a).weak.includes('missile')&&f.a.every(u=>u.confidence===0),'unanswered fire has a group reason instead of contradictory individual icons');
 const incoming=f.r.recent().in;f.r.dealt(incoming);tick(f,.1);ok(f.r.missilePressure===0,'successful retaliation can remove unanswered-fire pressure');
 f=start();r=f.r;r.mor=-1;tick(f,.01);ok(!r.routed&&r.state==='breaking'&&t.grpMorale(f.a).breaking===f.a.length,'the whole formation enters Breaking before routing');
 const time=r.breakT;f.b.paused=true;t.updateBattle(1);ok(r.breakT===time,'pausing does not advance a formation breaking timer');tick(f,t.RESOLVE.breakDelay);ok(r.routed&&f.a.every(u=>u.rout),'sustained collapse routes all living members together');
 ok(f.g.order==='rout'&&!f.g.hasTarget&&!f.g.queue.length,'routing clears tactical focus and queued movement');
 const x=f.g.ax;f.g.moveTo(800,200);f.g.attack(f.e[0]);f.g.hold();f.g.withdraw();ok(f.g.order==='rout'&&f.g.ax===x&&f.a.every(u=>u.rout),'ordinary orders cannot override a routed formation');
 const events=L.session.telemetry.groups[f.g.id].events.filter(e=>e.type==='group_routed').length;t.rout(f.a[0]);ok(L.session.telemetry.groups[f.g.id].events.filter(e=>e.type==='group_routed').length===events,'repeated route requests produce one formation transition');
 f.e.forEach(u=>u.x=900);for(let i=0;i<12&&!r.rallied;i++)tick(f,1);ok(r.rallied&&!r.routed&&f.a.every(u=>!u.rout)&&f.g.order==='hold','a safe formation rallies once as a group and returns to Hold');
 t.rout(f.a[0]);ok(r.shattered&&f.a.every(u=>u.rout&&u.shattered),'a second break shatters the entire formation');for(let i=0;i<20;i++)tick(f,1);ok(r.routed&&r.shattered,'a shattered formation cannot rally again');
 f=start();f.g.withdraw();tick(f,.1);ok(!f.r.routed&&f.r.confidence===0&&f.g.order==='withdraw','ordered withdrawal is distinct from automatic routing');
 f=start(20,20,{morale:false});f.r.mor=-100;tick(f,10);ok(!f.r.routed,'morale-disabled laboratory battles do not make automatic routing decisions');
 f=start(20,20,{leftGroups:[{type:'hum_foot',count:20},{type:'hero',count:1},{type:'brann',count:1},{type:'troll',count:1}]});const immune=f.b.units.filter(u=>!u.team&&t.steady(u));immune.forEach(u=>t.rout(u));ok(immune.every(u=>!t.resolveOf(u)&&!u.rout),'heroes, companion templates and unbreakable creatures retain their immunity');
 const hero=f.b.hero;f.r.confidence=1;f.r.mor=60;t.applyDmg(hero,hero.hp+1,1,'slash',f.e[0]);ok(f.r.confidence===0&&f.r.mor===40&&f.r.confidenceBlockedUntil>f.b.t,'leader loss applies once to each formation and overrides confidence');
 f=start(20,20);f.r.mor=20;t.moraleCry([...f.a,...f.a]);ok(f.r.mor===35,'War Cry heartens a formation once, not once per recipient soldier');
 f.r.mor=0;f.r.breakT=.4;f.r.mor=5;tick(f,0);ok(!f.r.breakT,'positive shared morale resets the breaking episode');
 f=start(20,20,{leftGroups:[{type:'hum_foot',count:10},{type:'hum_foot',count:10},{type:'hum_foot',count:10}]});const groups=t.playerGroups().map(id=>f.b.groups[id]);groups.forEach((g,i)=>{g.units.forEach(u=>{u.x=300+i*20;u.y=300});g.resolve.mor=i?5:0});
 t.rout(groups[0].units[0]);tick(f,0);ok(groups[1].resolve.mor<0&&!groups[1].resolve.routed&&!groups[2].resolve.routed,'nearby group panic is deferred and cannot cascade in the same update');
 const shocked=groups[1].resolve.mor;t.rout(groups[0].units[0]);tick(f,0);ok(groups[1].resolve.mor===shocked,'a repeated route event cannot multiply the neighbouring shock');
 f.b.units.reverse();tick(f,.01);ok(!groups[1].resolve.routed&&groups[1].resolve.breakT>0,'neighbouring groups must sustain their own breaking period');
 const owner=groups[2].resolve,groupMembers=groups[2].units;owner.mor=12;owner.sync();groupMembers[0].mor=99;ok(Math.abs(t.grpMorale(groupMembers).v-.12)<1e-8,'HUD reads shared resolve rather than averaging contradictory unit mirrors');
 L.sampleMorale(true);const sample=L.report().groups[groups[2].id].morale.at(-1);ok(sample.average===12&&sample.minimum===12&&sample.state===owner.state,'lab history samples the same shared value and state as the HUD');
 // the enemy commander reads the same shared resolve: a beaten army falls back instead of fighting to the last man
 const army=(left,right,extra={})=>{if(L.active)L.exit();L.start({leftGroups:[{type:'hum_foot',count:left}],rightGroups:[{type:'hum_foot',count:right}],morale:true,deploy:false,paused:true,ai:false,seed:42,...extra});const b=t.B;b.obs=[];b.units.forEach(u=>{u.x=u.team?560:400;u.y=300});return {b,foe:Object.values(b.groups).filter(g=>g.foe),mine:t.playerGroups().map(id=>b.groups[id])}};
 let w=army(40,12);t.command(1);ok(w.foe.every(g=>g.order!=='withdraw')&&!w.b.fallBack,'an outnumbered enemy army with steady morale keeps fighting');
 w.foe.forEach(g=>{g.resolve.mor=10});t.command(1);ok(w.foe.every(g=>g.order==='withdraw')&&w.b.fallBack&&G.msgs.some(m=>/enemy falls back/.test(m.m)),'a beaten enemy army with failing shared morale falls back as one');
 w.foe.forEach(g=>{g.resolve.mor=80});t.command(1);t.command(1);ok(w.foe.every(g=>g.order==='withdraw'),'once begun, the fall-back is not undone by later commander ticks');
 w=army(12,40);w.b.auto=true;w.mine.forEach(g=>{g.resolve.mor=5});t.command(1);ok(w.mine.every(g=>g.order!=='withdraw'),'your own army never withdraws on its own, even under AI command');
 w=army(40,12);w.b.noMorale=true;w.foe.forEach(g=>{g.resolve.mor=5});t.command(1);ok(w.foe.every(g=>g.order!=='withdraw'),'morale-free battles never fall back');
 w=army(40,12);const n0=w.b.units.filter(u=>u.team===1).length;w.foe.forEach(g=>{g.resolve.mor=10});w.b.units.filter(u=>u.team===1).forEach(u=>u.x=t.BW-60);for(let i=0;i<40&&!L.session.result;i++)L.step(30);
 ok(L.session.result==='Left side wins'&&w.b.units.some(u=>u.team===1&&u.left)&&w.b.kills<n0,'a fall-back ends the battle as a win, the escaped enemy alive and not counted as kills');
 L.restart();ok(Object.values(t.B.groups).filter(g=>g.resolve).every(g=>!g.resolve.routed&&!g.resolve.events.length&&g.resolve.mor===g.resolve.base),'restart creates clean independent formation resolve state');
}catch(e){o.push('EXC '+e.message+' '+e.stack)}finally{if(L.active)L.exit()}
 const d=document.createElement('pre');d.id='OUT';d.textContent=o.concat(ERR.map(e=>'ERR '+e)).join('\n');document.body.appendChild(d);
};
